//! W-180: Ruff's `D401` (`py/non-imperative-mood`) and `D421`
//! (`py/property-docstring-starts-with-verb`).
//!
//! `D401` reads the pack's table `python/imperatives`
//! (`data/python/imperatives.json`, generated by `scripts/data-imperatives.py`
//! from pydocstyle 6.3.0's two word lists, L11 D-56): the imperative form of
//! about 230 verbs, and a blacklist of first words (`this`, `the`,
//! `constructor`) that mark a docstring as not imperative. A docstring's first
//! word is judged as pydocstyle and Ruff judge it: a blacklisted word is
//! wrong; otherwise the word is stemmed, and when the stem is a listed verb's,
//! the word must be that verb's imperative form (`returns` and `returning` are
//! not, `return` is). A word whose stem is no listed verb's is not judged.
//!
//! The stemmer is [`stem`], written fresh for codelaw from the published
//! Snowball English ("Porter2") algorithm: no stemming library is a dependency
//! (L11). `D421` needs no table: Ruff's rule has its own ten verbs.
//!
//! Behaviour is Ruff 0.17's (MIT; its source read over the network, research
//! only, L5); every line here is written fresh.

use crate::python_util::{decorator_target, decorators, qualified_name, PY};
use crate::{NativeContext, NativeFinding, NativeRule};
use codelaw_core::Language;
use codelaw_lang::SyntaxNode;
use std::cell::RefCell;
use std::collections::{BTreeMap, BTreeSet};
use std::rc::Rc;
use std::sync::Arc;
use tree_sitter::Node;

// ---------------------------------------------------------------- stemmer

fn vowel(b: u8) -> bool {
    matches!(b, b'a' | b'e' | b'i' | b'o' | b'u' | b'y')
}

/// The word's R1 or R2 from `from`: the position after the first non-vowel
/// that follows a vowel, or the word's end when there is none.
fn region(w: &[u8], from: usize) -> usize {
    let mut i = from;
    while i < w.len() && !vowel(w[i]) {
        i += 1;
    }
    while i < w.len() && vowel(w[i]) {
        i += 1;
    }
    (i + 1).min(w.len())
}

/// Whether `w` ends in a short syllable: a vowel followed by a non-vowel
/// other than `w`, `x` or `Y`, and preceded by a non-vowel; or a vowel at the
/// start of the word followed by a non-vowel.
fn short_syllable(w: &[u8]) -> bool {
    match w {
        [.., a, b, c] if !vowel(*a) && vowel(*b) && !vowel(*c) && !matches!(*c, b'w' | b'x' | b'Y') => true,
        [a, b] => vowel(*a) && !vowel(*b),
        _ => false,
    }
}

/// The longest of `suffixes` that ends `w`.
fn longest<'s>(w: &[u8], suffixes: &[&'s str]) -> Option<&'s str> {
    suffixes.iter().filter(|s| w.ends_with(s.as_bytes())).max_by_key(|s| s.len()).copied()
}

fn replace_suffix(w: &mut Vec<u8>, cut: usize, with: &str) {
    w.truncate(w.len() - cut);
    w.extend_from_slice(with.as_bytes());
}

/// The Snowball English stemmer ("Porter2"): `returns`, `returning` and
/// `returned` all stem to `return`. `word` is lower case; a word with a
/// character outside ASCII is returned as it is (no listed verb has one).
/// Step 0 (a trailing `'s`) is left out: callers strip everything but
/// letters and digits first.
pub(crate) fn stem(word: &str) -> String {
    if !word.is_ascii() {
        return word.to_owned();
    }
    match word {
        "skis" => return "ski".into(),
        "skies" => return "sky".into(),
        "dying" => return "die".into(),
        "lying" => return "lie".into(),
        "tying" => return "tie".into(),
        "idly" => return "idl".into(),
        "gently" => return "gentl".into(),
        "ugly" => return "ugli".into(),
        "early" => return "earli".into(),
        "only" => return "onli".into(),
        "singly" => return "singl".into(),
        "sky" | "news" | "howe" | "atlas" | "cosmos" | "bias" | "andes" => return word.to_owned(),
        _ => {}
    }
    if word.len() <= 2 {
        return word.to_owned();
    }
    let mut w: Vec<u8> = word.bytes().collect();
    // A `y` that starts the word or follows a vowel is a consonant.
    for i in 0..w.len() {
        if w[i] == b'y' && (i == 0 || vowel(w[i - 1])) {
            w[i] = b'Y';
        }
    }
    let p1 = if w.starts_with(b"gener") || w.starts_with(b"arsen") {
        5
    } else if w.starts_with(b"commun") {
        6
    } else {
        region(&w, 0)
    };
    let p2 = if p1 < w.len() { region(&w, p1) } else { w.len() };

    // Step 1a
    match longest(&w, &["sses", "ied", "ies", "ss", "us", "s"]) {
        Some("sses") => replace_suffix(&mut w, 2, ""),
        Some("ied" | "ies") => {
            let more_than_one = w.len() - 3 > 1;
            replace_suffix(&mut w, 3, if more_than_one { "i" } else { "ie" });
        }
        // Deleted when the part before holds a vowel that is not the letter before the `s`.
        Some("s") if w[..w.len() - 2].iter().any(|b| vowel(*b)) => {
            w.pop();
        }
        _ => {}
    }
    if matches!(&w[..], b"inning" | b"outing" | b"canning" | b"herring" | b"earring" | b"proceed" | b"exceed" | b"succeed") {
        return String::from_utf8_lossy(&w).into_owned();
    }

    // Step 1b
    if let Some(s) = longest(&w, &["eedly", "ingly", "edly", "eed", "ing", "ed"]) {
        let start = w.len() - s.len();
        if s == "eed" || s == "eedly" {
            if start >= p1 {
                replace_suffix(&mut w, s.len(), "ee");
            }
        } else if w[..start].iter().any(|b| vowel(*b)) {
            w.truncate(start);
            if w.ends_with(b"at") || w.ends_with(b"bl") || w.ends_with(b"iz") {
                w.push(b'e');
            } else if matches!(&w[w.len().saturating_sub(2)..], b"bb" | b"dd" | b"ff" | b"gg" | b"mm" | b"nn" | b"pp" | b"rr" | b"tt") {
                w.pop();
            } else if w.len() == p1 && short_syllable(&w) {
                w.push(b'e');
            }
        }
    }

    // Step 1c: a final y after a non-vowel that is not the first letter.
    if w.len() > 2 && matches!(w[w.len() - 1], b'y' | b'Y') && !vowel(w[w.len() - 2]) {
        let n = w.len();
        w[n - 1] = b'i';
    }

    // Step 2: in R1.
    const STEP2: [&str; 24] = [
        "tional", "enci", "anci", "abli", "entli", "izer", "ization", "ational", "ation", "ator", "alism", "aliti", "alli", "fulness", "ousli",
        "ousness", "iveness", "iviti", "biliti", "bli", "ogi", "fulli", "lessli", "li",
    ];
    if let Some(s) = longest(&w, &STEP2) {
        let start = w.len() - s.len();
        if start >= p1 {
            match s {
                "tional" => replace_suffix(&mut w, s.len(), "tion"),
                "enci" => replace_suffix(&mut w, s.len(), "ence"),
                "anci" => replace_suffix(&mut w, s.len(), "ance"),
                "abli" => replace_suffix(&mut w, s.len(), "able"),
                "entli" => replace_suffix(&mut w, s.len(), "ent"),
                "izer" | "ization" => replace_suffix(&mut w, s.len(), "ize"),
                "ational" | "ation" | "ator" => replace_suffix(&mut w, s.len(), "ate"),
                "alism" | "aliti" | "alli" => replace_suffix(&mut w, s.len(), "al"),
                "fulness" | "fulli" => replace_suffix(&mut w, s.len(), "ful"),
                "ousli" | "ousness" => replace_suffix(&mut w, s.len(), "ous"),
                "iveness" | "iviti" => replace_suffix(&mut w, s.len(), "ive"),
                "biliti" | "bli" => replace_suffix(&mut w, s.len(), "ble"),
                "lessli" => replace_suffix(&mut w, s.len(), "less"),
                // `ogi` after an `l` becomes `og`.
                "ogi" => {
                    if start > 0 && w[start - 1] == b'l' {
                        replace_suffix(&mut w, s.len(), "og");
                    }
                }
                // `li` after c d e g h k m n r t is dropped.
                _ => {
                    if start > 0 && matches!(w[start - 1], b'c' | b'd' | b'e' | b'g' | b'h' | b'k' | b'm' | b'n' | b'r' | b't') {
                        w.truncate(start);
                    }
                }
            }
        }
    }

    // Step 3: in R1.
    if let Some(s) = longest(&w, &["tional", "ational", "alize", "icate", "iciti", "ical", "ful", "ness", "ative"]) {
        let start = w.len() - s.len();
        if start >= p1 {
            match s {
                "tional" => replace_suffix(&mut w, s.len(), "tion"),
                "ational" => replace_suffix(&mut w, s.len(), "ate"),
                "alize" => replace_suffix(&mut w, s.len(), "al"),
                "icate" | "iciti" | "ical" => replace_suffix(&mut w, s.len(), "ic"),
                "ful" | "ness" => w.truncate(start),
                // `ative`, in R2 only.
                _ => {
                    if start >= p2 {
                        w.truncate(start);
                    }
                }
            }
        }
    }

    // Step 4: in R2.
    let step4 = ["al", "ance", "ence", "er", "ic", "able", "ible", "ant", "ement", "ment", "ent", "ism", "ate", "iti", "ous", "ive", "ize", "ion"];
    if let Some(s) = longest(&w, &step4) {
        let start = w.len() - s.len();
        if start >= p2 && (s != "ion" || (start > 0 && matches!(w[start - 1], b's' | b't'))) {
            w.truncate(start);
        }
    }

    // Step 5
    match w.last() {
        Some(b'e') => {
            let start = w.len() - 1;
            if start >= p2 || (start >= p1 && !short_syllable(&w[..start])) {
                w.pop();
            }
        }
        Some(b'l') => {
            let start = w.len() - 1;
            if start >= p2 && start > 0 && w[start - 1] == b'l' {
                w.pop();
            }
        }
        _ => {}
    }

    for b in &mut w {
        if *b == b'Y' {
            *b = b'y';
        }
    }
    String::from_utf8_lossy(&w).into_owned()
}

// -------------------------------------------------------------- the table

/// The table `python/imperatives`: verbs by stem, and the blacklist.
pub(crate) struct Mood {
    by_stem: BTreeMap<String, BTreeSet<String>>,
    blacklist: BTreeSet<String>,
}

impl Mood {
    pub(crate) fn from_table(table: &serde_json::Value) -> Option<Mood> {
        let words = |key: &str| -> Option<Vec<&str>> { Some(table.get(key)?.as_array()?.iter().filter_map(|v| v.as_str()).collect()) };
        let mut by_stem: BTreeMap<String, BTreeSet<String>> = BTreeMap::new();
        for verb in words("imperatives")? {
            by_stem.entry(stem(verb)).or_default().insert(verb.to_owned());
        }
        Some(Mood { by_stem, blacklist: words("blacklist")?.into_iter().map(str::to_owned).collect() })
    }

    /// `Some(false)` for a word that is not imperative (blacklisted, or a
    /// listed verb's other form), `Some(true)` for a listed verb's
    /// imperative, `None` for a word the table does not judge. `word` is
    /// lower case.
    pub(crate) fn is_imperative(&self, word: &str) -> Option<bool> {
        if self.blacklist.contains(word) {
            return Some(false);
        }
        // Ruff's own addition: the stem of `added` is `ad`, not `add`.
        let s = if word == "added" { "add".to_owned() } else { stem(word) };
        Some(self.by_stem.get(&s)?.contains(word))
    }
}

type MoodCache = Option<(usize, Option<Rc<Mood>>)>;

thread_local! {
    /// The table of the last pack data seen on this thread, by the address
    /// of its JSON (one per pack load), so a function's check does not
    /// stem 230 words again.
    static MOOD: RefCell<MoodCache> = const { RefCell::new(None) };
}

fn mood_of(ctx: &NativeContext<'_>) -> Option<Rc<Mood>> {
    let table: &Arc<serde_json::Value> = ctx.data.get("python/imperatives")?;
    let key = Arc::as_ptr(table) as usize;
    MOOD.with(|m| {
        let mut m = m.borrow_mut();
        if let Some((k, mood)) = &*m
            && *k == key
        {
            return mood.clone();
        }
        let mood = Mood::from_table(table).map(Rc::new);
        *m = Some((key, mood.clone()));
        mood
    })
}

// ------------------------------------------------------------------ rules

/// Ruff's `normalize_word`: letters and digits only, lower case.
fn normalize(word: &str) -> String {
    word.chars().filter(|c| c.is_alphanumeric()).flat_map(char::to_lowercase).collect()
}

fn option_names(ctx: &NativeContext<'_>, key: &str) -> Vec<String> {
    ctx.options.get(key).and_then(|v| v.as_array()).into_iter().flatten().filter_map(|v| v.as_str()).map(str::to_owned).collect()
}

/// Ruff's `is_property`: the decorators that make a function a property,
/// as qualified names — `property`, `functools.cached_property`,
/// `abc.abstractproperty`, `types.DynamicClassAttribute` — and the
/// `property_decorators` option.
fn is_property(names: &[String], ctx: &NativeContext<'_>) -> bool {
    let extra = option_names(ctx, "property_decorators");
    names.iter().any(|n| {
        matches!(n.as_str(), "builtins.property" | "enum.property" | "functools.cached_property" | "abc.abstractproperty" | "types.DynamicClassAttribute")
            || extra.contains(n)
    })
}

/// What a function's docstring says about its first line.
struct First<'a> {
    /// The docstring's whole text, quotes included.
    start: usize,
    end: usize,
    /// The first line without surrounding whitespace.
    line: &'a str,
    /// The first word of `line`, where it begins in the file.
    word: &'a str,
    word_at: usize,
}

/// The first line and first word of a function's docstring, and whether the
/// function is a property; `None` for a function with no docstring, one that
/// an `ignore_decorators` entry skips, or one with an empty first line.
/// Ruff finds the first line after `trim` for `D401` and `trim_start` for
/// `D421`, which differ only when the docstring ends in blank lines.
fn first_line<'a>(def: Node<'a>, ctx: &NativeContext<'a>) -> Option<(First<'a>, bool)> {
    let model = ctx.semantic?;
    let names: Vec<String> = decorators(def).into_iter().filter_map(|d| qualified_name(decorator_target(d), model, ctx.source)).collect();
    let ignored = option_names(ctx, "ignore_decorators");
    if names.iter().any(|n| ignored.contains(n)) {
        return None;
    }
    let ds = crate::py_ruff_doc::docstring_of(def, ctx.source)?;
    let body = &ctx.source[ds.body_start..ds.body_end];
    let trimmed = body.trim_start();
    let lead = body.len() - trimmed.len();
    let line = trimmed.lines().next()?.trim();
    let word = line.split_whitespace().next()?;
    // `word` starts the line, which starts the trimmed body.
    Some((First { start: ds.start, end: ds.end, line, word, word_at: ds.body_start + lead }, is_property(&names, ctx)))
}

fn is_test(name: &str) -> bool {
    name == "runTest" || name.starts_with("test")
}

pub struct NonImperativeMood;

impl NativeRule for NonImperativeMood {
    fn id(&self) -> &'static str {
        "py/non-imperative-mood"
    }
    fn languages(&self) -> &'static [Language] {
        PY
    }
    fn kinds(&self) -> &'static [&'static str] {
        &["function_definition"]
    }
    fn needs_semantic(&self) -> bool {
        true
    }
    fn check(&self, node: SyntaxNode<'_>, ctx: &NativeContext<'_>, out: &mut Vec<NativeFinding>) {
        let def = node.get_inner_node();
        let Some(name) = def.child_by_field_name("name") else { return };
        if is_test(&ctx.source[name.start_byte()..name.end_byte()]) {
            return;
        }
        let Some(mood) = mood_of(ctx) else { return };
        let Some((first, property)) = first_line(def, ctx) else { return };
        if property {
            return;
        }
        let norm = normalize(first.word);
        if norm.is_empty() || mood.is_imperative(&norm) != Some(false) {
            return;
        }
        out.push(NativeFinding {
            start: first.start,
            end: first.end,
            message: format!("First line of the docstring should be in the imperative mood: \"{}\"", first.line),
            edits: Vec::new(),
        });
    }
}

/// The verbs Ruff's `D421` refuses to open a property's docstring.
const PROPERTY_VERBS: [&str; 10] = ["return", "returns", "get", "gets", "yield", "yields", "fetch", "fetches", "retrieve", "retrieves"];

pub struct PropertyDocstringStartsWithVerb;

impl NativeRule for PropertyDocstringStartsWithVerb {
    fn id(&self) -> &'static str {
        "py/property-docstring-starts-with-verb"
    }
    fn languages(&self) -> &'static [Language] {
        PY
    }
    fn kinds(&self) -> &'static [&'static str] {
        &["function_definition"]
    }
    fn needs_semantic(&self) -> bool {
        true
    }
    fn check(&self, node: SyntaxNode<'_>, ctx: &NativeContext<'_>, out: &mut Vec<NativeFinding>) {
        let Some((first, property)) = first_line(node.get_inner_node(), ctx) else { return };
        if !property {
            return;
        }
        let norm = normalize(first.word);
        if PROPERTY_VERBS.contains(&norm.as_str()) {
            out.push(NativeFinding {
                start: first.word_at,
                end: first.word_at + first.word.len(),
                message: format!("The docstring of a property should not start with a verb (\"{}\")", first.word),
                edits: Vec::new(),
            });
        }
    }
}

pub static RULES: &[&dyn NativeRule] = &[&NonImperativeMood, &PropertyDocstringStartsWithVerb];

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::BTreeMap;

    fn stems(pairs: &[(&str, &str)]) {
        for (word, want) in pairs {
            assert_eq!(stem(word), *want, "{word}");
        }
    }

    #[test]
    fn stemmer_follows_the_published_algorithm() {
        stems(&[
            // the steps, one word each
            ("caresses", "caress"), ("ponies", "poni"), ("ties", "tie"), ("cries", "cri"), ("gas", "gas"), ("this", "this"), ("kiwis", "kiwi"),
            ("bus", "bus"), ("pass", "pass"), ("feed", "feed"), ("agreed", "agre"), ("plastered", "plaster"), ("bled", "bled"), ("motoring", "motor"),
            ("sing", "sing"), ("conflated", "conflat"), ("troubled", "troubl"), ("sized", "size"), ("hopping", "hop"), ("hoping", "hope"),
            ("falling", "fall"), ("hissing", "hiss"), ("filing", "file"), ("failing", "fail"), ("happy", "happi"), ("sky", "sky"), ("by", "by"),
            ("say", "say"), ("cry", "cri"), ("relational", "relat"), ("conditional", "condit"), ("rational", "ration"), ("valenci", "valenc"),
            ("hesitancy", "hesit"), ("digitizer", "digit"), ("conformabli", "conform"), ("radicalli", "radic"), ("differentli", "differ"),
            ("vileli", "vile"), ("analogousli", "analog"), ("vietnamization", "vietnam"), ("predication", "predic"), ("operator", "oper"),
            ("feudalism", "feudal"), ("decisiveness", "decis"), ("hopefulness", "hope"), ("callousness", "callous"), ("formaliti", "formal"),
            ("sensitiviti", "sensit"), ("sensibiliti", "sensibl"), ("triplicate", "triplic"), ("formative", "format"), ("formalize", "formal"),
            ("electriciti", "electr"), ("electrical", "electr"), ("hopeful", "hope"), ("goodness", "good"), ("revival", "reviv"),
            ("allowance", "allow"), ("inference", "infer"), ("airliner", "airlin"), ("gyroscopic", "gyroscop"), ("adjustable", "adjust"),
            ("defensible", "defens"), ("irritant", "irrit"), ("replacement", "replac"), ("adjustment", "adjust"), ("dependent", "depend"),
            ("adoption", "adopt"), ("homologou", "homologou"), ("communism", "communism"), ("activate", "activ"), ("angulariti", "angular"),
            ("homologous", "homolog"), ("effective", "effect"), ("bowdlerize", "bowdler"), ("probate", "probat"), ("rate", "rate"),
            ("cease", "ceas"), ("controll", "control"), ("roll", "roll"),
            // the exceptions
            ("skis", "ski"), ("skies", "sky"), ("dying", "die"), ("lying", "lie"), ("tying", "tie"), ("idly", "idl"), ("gently", "gentl"),
            ("ugly", "ugli"), ("early", "earli"), ("only", "onli"), ("singly", "singl"), ("news", "news"), ("howe", "howe"), ("atlas", "atlas"),
            ("cosmos", "cosmos"), ("bias", "bias"), ("andes", "andes"), ("inning", "inning"), ("outing", "outing"), ("canning", "canning"),
            ("herring", "herring"), ("earring", "earring"), ("proceed", "proceed"), ("exceed", "exceed"), ("succeed", "succeed"),
            // the prefixes that keep R1 after them
            ("generate", "generat"), ("general", "general"), ("communication", "communic"), ("arsenal", "arsenal"),
            // short words and a consonant `y`
            ("at", "at"), ("be", "be"), ("yes", "yes"), ("yield", "yield"), ("yielding", "yield"), ("played", "play"), ("displays", "display"),
        ]);
    }

    #[test]
    fn a_verb_and_its_regular_forms_share_a_stem() {
        for (verb, forms) in [
            ("return", ["returns", "returning", "returned"]),
            ("fetch", ["fetches", "fetching", "fetched"]),
            ("yield", ["yields", "yielding", "yielded"]),
            ("retrieve", ["retrieves", "retrieving", "retrieved"]),
            ("create", ["creates", "creating", "created"]),
            ("write", ["writes", "writing", "written"]),
            ("try", ["tries", "trying", "tried"]),
            ("apply", ["applies", "applying", "applied"]),
            ("stop", ["stops", "stopping", "stopped"]),
            ("use", ["uses", "using", "used"]),
        ] {
            let base = stem(verb);
            for form in forms {
                // `written` is an irregular form: its own stem.
                if form != "written" {
                    assert_eq!(stem(form), base, "{form} / {verb}");
                }
            }
        }
        // The stem of `add` loses its second `d` in `adding`: pydocstyle and Ruff do not judge it.
        assert_eq!((stem("add"), stem("adding")), ("add".to_owned(), "ad".to_owned()));
    }

    fn real_table() -> serde_json::Value {
        let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../packs/python/data/python/imperatives.json");
        serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
    }

    #[test]
    fn the_table_judges_first_words_as_pydocstyle_does() {
        let mood = Mood::from_table(&real_table()).unwrap();
        for (word, want) in [
            ("return", Some(true)), ("returns", Some(false)), ("returning", Some(false)), ("returned", Some(false)), ("get", Some(true)),
            ("gets", Some(false)), ("add", Some(true)), ("adds", Some(false)), ("added", Some(false)), ("adding", None),
            ("this", Some(false)), ("the", Some(false)), ("constructor", Some(false)), ("a", Some(false)), ("run", Some(true)), ("runs", Some(false)),
            ("ran", None), ("frobnicate", None), ("widget", None), ("is", None), ("tries", Some(false)), ("try", Some(true)), ("hello", None),
        ] {
            assert_eq!(mood.is_imperative(word), want, "{word}");
        }
    }

    #[test]
    fn normalizing_keeps_letters_and_digits() {
        assert_eq!(normalize("Returns:"), "returns");
        assert_eq!(normalize("\"Get"), "get");
        assert_eq!(normalize("..."), "");
        assert_eq!(normalize("v2"), "v2");
    }

    #[test]
    fn the_rules_judge_a_functions_docstring() {
        use std::sync::Arc;
        let table = Arc::new(real_table());
        let mut data = BTreeMap::new();
        data.insert("python/imperatives".to_owned(), table);
        let run = |rule: &dyn NativeRule, src: &str| {
            let root = codelaw_lang::parse(Language::Python, src);
            let model = codelaw_semantic::build(Language::Python, &root, src);
            let options = BTreeMap::new();
            let file = crate::DetachedFile::new("example.py".to_owned(), src);
            let ctx = NativeContext { source: src, language: Language::Python, semantic: model.as_ref(), options: &options, data: &data, file: &file };
            let mut out = Vec::new();
            for n in root.root().dfs() {
                if rule.kinds().contains(&n.kind().as_ref()) {
                    rule.check(n, &ctx, &mut out);
                }
            }
            out
        };
        let hit = |src: &str| run(&NonImperativeMood, src).len();
        assert_eq!(hit("def f():\n    \"\"\"Returns the value.\"\"\"\n"), 1);
        assert_eq!(hit("def f():\n    \"\"\"Return the value.\"\"\"\n"), 0);
        assert_eq!(hit("def f():\n    \"\"\"\n    Returns the value.\n    \"\"\"\n"), 1);
        assert_eq!(hit("def test_f():\n    \"\"\"Returns the value.\"\"\"\n"), 0);
        assert_eq!(hit("def f():\n    \"\"\"This returns the value.\"\"\"\n"), 1);
        assert_eq!(hit("@property\ndef f(self):\n    \"\"\"Returns the value.\"\"\"\n"), 0);
        assert_eq!(hit("def f():\n    \"\"\"Widget for the value.\"\"\"\n"), 0);
        assert_eq!(hit("def f():\n    pass\n"), 0);
        assert_eq!(hit("def f():\n    \"\"\"   \"\"\"\n"), 0);
        let hit421 = |src: &str| run(&PropertyDocstringStartsWithVerb, src).len();
        assert_eq!(hit421("@property\ndef f(self):\n    \"\"\"Returns the value.\"\"\"\n"), 1);
        assert_eq!(hit421("@property\ndef f(self):\n    \"\"\"The value.\"\"\"\n"), 0);
        assert_eq!(hit421("def f(self):\n    \"\"\"Returns the value.\"\"\"\n"), 0);
        assert_eq!(hit421("from functools import cached_property\n\n@cached_property\ndef f(self):\n    \"\"\"Get the value.\"\"\"\n"), 1);
    }
}
